import{_ as a,o as s,c as n,ae as o}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),t={name:"guide/concepts.md"};function i(c,e,l,d,r,p){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="ai-hallucination" tabindex="-1">AI Hallucination <a class="header-anchor" href="#ai-hallucination" aria-label="Permalink to &quot;AI Hallucination&quot;">​</a></h2><p>When an AI assistant generates code (like ChatGPT, Claude, Copilot), it sometimes invents package names that do not exist on npm. These are called <strong>AI hallucinations</strong> — also referred to as <strong>slopsquatting</strong>.</p><p>Sentinel-AI detects these by cross-referencing every import against the npm registry. If the package returns a 404, it is flagged as an AI hallucination.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span> AI HALLUCINATIONS (1)</span></span>
<span class="line"><span>   ai-slopsquatting         ← not found on npm</span></span></code></pre></div><h2 id="shadow-code" tabindex="-1">Shadow Code <a class="header-anchor" href="#shadow-code" aria-label="Permalink to &quot;Shadow Code&quot;">​</a></h2><p>A package that <strong>exists on npm</strong> but is <strong>not declared in <code>package.json</code></strong>. This could mean:</p><ul><li>The package was imported manually without being added to <code>package.json</code></li><li>An AI hallucinated a real package name (it exists, but shouldn&#39;t be used)</li><li>The import was copied from another project</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span> SHADOW CODE (1)</span></span>
<span class="line"><span>   @swc</span></span></code></pre></div><h2 id="node-js-built-in-modules" tabindex="-1">Node.js Built-in Modules <a class="header-anchor" href="#node-js-built-in-modules" aria-label="Permalink to &quot;Node.js Built-in Modules&quot;">​</a></h2><p>Packages like <code>fs</code>, <code>path</code>, <code>crypto</code> are Node.js runtime modules, not npm packages. Sentinel-AI automatically filters them out to avoid false positives.</p><p>List includes: <code>fs</code>, <code>path</code>, <code>crypto</code>, <code>http</code>, <code>https</code>, <code>net</code>, <code>tls</code>, <code>os</code>, <code>child_process</code>, <code>url</code>, <code>buffer</code>, <code>stream</code>, <code>util</code>, <code>events</code>, and more.</p><h2 id="vulnerability-scan-deep-mode" tabindex="-1">Vulnerability Scan (Deep Mode) <a class="header-anchor" href="#vulnerability-scan-deep-mode" aria-label="Permalink to &quot;Vulnerability Scan (Deep Mode)&quot;">​</a></h2><p>When <code>--deep</code> is enabled, Sentinel-AI queries the <a href="https://osv.dev" target="_blank" rel="noreferrer">OSV (Open Source Vulnerabilities)</a> database, which aggregates data from:</p><ul><li><strong>GitHub Advisory Database</strong> (GHSA-*)</li><li><strong>Snyk</strong></li><li><strong>npm Security Advisories</strong></li></ul><p>All severity levels are reported: LOW, MEDIUM, HIGH, CRITICAL.</p><h2 id="malicious-packages-mal" tabindex="-1">Malicious Packages (MAL-*) <a class="header-anchor" href="#malicious-packages-mal" aria-label="Permalink to &quot;Malicious Packages (MAL-*)&quot;">​</a></h2><p>The OSV database also tracks <strong>confirmed malicious packages</strong> published to npm. These are flagged separately from regular vulnerabilities with a prominent <code>[MALICIOUS]</code> badge, as they represent a more severe threat.</p><h2 id="package-age-check" tabindex="-1">Package Age Check <a class="header-anchor" href="#package-age-check" aria-label="Permalink to &quot;Package Age Check&quot;">​</a></h2><p>A package published to npm less than 72 hours ago is flagged as suspicious, shown with a <code>[new &lt;72h]</code> badge. This is a heuristic — malicious packages are often uploaded, spread, and quickly removed within hours.</p><h2 id="batch-osv-query" tabindex="-1">Batch OSV Query <a class="header-anchor" href="#batch-osv-query" aria-label="Permalink to &quot;Batch OSV Query&quot;">​</a></h2><p>Instead of making one HTTP request per package, Sentinel-AI sends a <strong>single batch request</strong> to the OSV API (<code>POST /v1/querybatch</code>) containing all packages at once. This reduces latency from O(N) to O(1) for the vulnerability check.</p><h2 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h2><p>Requests to the npm registry are parallelized with a configurable concurrency limit (default: 5). Retry logic (max 3 attempts with exponential backoff: 1s → 2s → 4s) handles rate limiting (HTTP 429).</p><h2 id="transitive-dependencies" tabindex="-1">Transitive Dependencies <a class="header-anchor" href="#transitive-dependencies" aria-label="Permalink to &quot;Transitive Dependencies&quot;">​</a></h2><p>When <code>--deep</code> is enabled, Sentinel-AI reads <code>package-lock.json</code> and scans <strong>all</strong> transitive dependencies (not just packages you import directly). This catches vulnerabilities in packages that your dependencies use.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Your code: import &#39;axios&#39;</span></span>
<span class="line"><span>               ↓</span></span>
<span class="line"><span>axios uses: follow-redirects  (transitive dep)</span></span>
<span class="line"><span>               ↓</span></span>
<span class="line"><span>follow-redirects has CVE-2023-26159 (HIGH)</span></span></code></pre></div><p>Without <code>--deep</code>, <code>follow-redirects</code> would not be scanned. With <code>--deep</code>, it is included in the OSV batch query.</p><h3 id="origin-tracking" tabindex="-1">Origin tracking <a class="header-anchor" href="#origin-tracking" aria-label="Permalink to &quot;Origin tracking&quot;">​</a></h3><p>For each transitive vulnerability found, Sentinel-AI reports which direct dependency introduced it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span> TRANSITIVE VULNERABILITIES (2)</span></span>
<span class="line"><span>   follow-redirects (v2.4.1)    ← from axios@1.6.8</span></span>
<span class="line"><span>   qs (v0.6.6)                  ← from axios@1.6.8</span></span></code></pre></div><h3 id="include-dev" tabindex="-1"><code>--include-dev</code> <a class="header-anchor" href="#include-dev" aria-label="Permalink to &quot;\`--include-dev\`&quot;">​</a></h3><p>By default, only production transitive dependencies are scanned. Use <code>--include-dev</code> to also include dev-only transitive packages.</p><h2 id="version-resolution" tabindex="-1">Version Resolution <a class="header-anchor" href="#version-resolution" aria-label="Permalink to &quot;Version Resolution&quot;">​</a></h2><p>Sentinel-AI resolves the installed version of each package using priority order:</p><ol><li><strong>package-lock.json</strong> — exact version (always available, no <code>node_modules</code> needed)</li><li><strong><code>node_modules/&lt;pkg&gt;/package.json</code></strong> — exact version (requires <code>node_modules</code>)</li><li><strong>package.json</strong> — version range (fallback, least precise)</li></ol>`,37)])])}const g=a(t,[["render",i]]);export{u as __pageData,g as default};
